using CoreModels;
namespace BusinessLayer;
public record PolicyEvaluation(decimal score, string level, string decision, string reason, object features);
public class RiskPolicyEngine { public PolicyEvaluation Evaluate(IEnumerable<ScanResult> scans, IEnumerable<PolicyRule>? rules = null) { var s = scans.ToList(); int c = s.Sum(x => x.CriticalCount), h = s.Sum(x => x.HighCount), m = s.Sum(x => x.MediumCount), l = s.Sum(x => x.LowCount); decimal score = Math.Min(100, c * 25 + h * 6 + m * 2 + l * .25m); var active = rules?.Where(x => x.IsActive).ToList() ?? []; if (active.Any(x => x.RuleCode == "SECRET" && s.Any(y => y.ScanType == "GITLEAKS" && y.CriticalCount > 0))) return new(100, "CRITICAL", Statuses.Blocked, "Leaked secret detected", new { c, h, m, l }); if (c > 0) return new(Math.Max(score, 75), "CRITICAL", Statuses.Blocked, $"{c} critical finding(s)", new { c, h, m, l }); if (score >= 75) return new(score, "HIGH", Statuses.Blocked, "Risk score is at least 75", new { c, h, m, l }); if (score >= 50 || h >= 5) return new(score, "MEDIUM", Statuses.ManualReview, "Risk score or high-severity findings require review", new { c, h, m, l }); return new(score, "LOW", Statuses.Approved, "No blocking policy rule was triggered", new { c, h, m, l }); } }
